package com.thinking.ticket.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/* 영속 모델. 도메인 Ticket과 다른 클래스로 둔다 — 도메인은 JPA를 모르고 이 클래스는 예약 불변식을 모른다.
 * 하나로 겸용하면 저장 기술이 도메인의 모양을 규정하게 된다.
 *
 * 컬럼 이름을 @Column으로 못박는 이유: 스키마가 ddl-auto=update로 이 매핑에서 만들어지기 때문에,
 * 이름이 어긋나면 실패가 아니라 '다른 컬럼'이 조용히 하나 더 생긴다.
 * 식별자는 도메인이 이미 정해서 넘겨주므로 생성 전략을 두지 않는다. */
@Entity
@Table(name = "tickets")
public class TicketJpaEntity {

    @Id
    @Column(name = "id")
    private Long id;

    @Column(name = "price")
    private int price;

    @Column(name = "reserved")
    private boolean reserved;

    @Column(name = "suspended")
    private boolean suspended;

    @Column(name = "user_id")
    private long userId;

    /* JPA가 리플렉션으로 인스턴스를 만들 때만 쓰는 생성자. 코드에서 직접 부르지 않는다. */
    protected TicketJpaEntity() {
    }

    public TicketJpaEntity(Long id, int price, boolean reserved, boolean suspended, long userId) {
        this.id = id;
        this.price = price;
        this.reserved = reserved;
        this.suspended = suspended;
        this.userId = userId;
    }

    public Long getId() {
        return id;
    }

    public int getPrice() {
        return price;
    }

    public boolean isReserved() {
        return reserved;
    }

    public boolean isSuspended() {
        return suspended;
    }

    public long getUserId() {
        return userId;
    }
}

package com.thinking.ticket.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/* 회원의 영속 모델. 스키마 계약은 users(id, name)이다.
 * 티켓과 같은 이유로 도메인 User와 분리한다 — Core에는 순수 도메인 객체만 오간다. */
@Entity
@Table(name = "users")
public class UserJpaEntity {

    @Id
    @Column(name = "id")
    private Long id;

    @Column(name = "name")
    private String name;

    /* JPA 전용 생성자. */
    protected UserJpaEntity() {
    }

    public UserJpaEntity(Long id, String name) {
        this.id = id;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}

package com.thinking.ticket.adapter.out.persistence;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/* Spring Data가 구현을 만들어 주는 기술 세부. Core는 이 타입을 모르고
 * TicketRepository(아웃바운드 포트)만 안다. */
public interface TicketJpaRepository extends JpaRepository<TicketJpaEntity, Long> {

    /* 예약 확정을 '아직 예약되지 않은 행'에만 적용한다.
     *
     * 조회하고 판단하고 저장하는 사이에 다른 인스턴스가 먼저 예약을 확정할 수 있다.
     * 그때 읽어둔 상태를 그대로 덮어쓰면 뒤늦은 예약이 앞선 예약을 지워 이중 판매가 된다.
     * 조건을 UPDATE 문 안으로 넣어 그 틈을 DB의 원자적 연산 한 번으로 닫는다.
     * (version 컬럼을 둔 낙관적 잠금이 아니라 이 방식을 쓴 이유는 스키마 계약에 version이 없기 때문이다.)
     *
     * clearAutomatically: 벌크 UPDATE는 영속성 컨텍스트를 우회하므로, 남아 있는 1차 캐시를
     * 비워 뒤이은 조회가 낡은 상태를 보지 않게 한다. */
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("update TicketJpaEntity t set t.reserved = true, t.userId = :userId "
            + "where t.id = :ticketId and t.reserved = false")
    int reserveIfNotReserved(@Param("ticketId") long ticketId, @Param("userId") long userId);
}

package com.thinking.ticket.adapter.out.persistence;

import org.springframework.data.jpa.repository.JpaRepository;

/* 회원 조회만 필요하므로 기본 제공 메서드 외에 추가하지 않는다. */
public interface UserJpaRepository extends JpaRepository<UserJpaEntity, Long> {
}

package com.thinking.ticket.adapter.out.persistence;

import com.thinking.ticket.core.domain.Ticket;

/* 도메인 모델 ↔ 영속 모델 변환. 분리를 택한 대가를 이 어댑터 안에서 치른다 —
 * 변환이 Core로 새면 Core가 영속 모델을 알게 된다.
 *
 * 상태 복원에는 rehydrate를 쓴다. assignTo/suspend는 '전이'라서 이미 예약된 행을 되살릴 때
 * 불변식에 걸리고, 애초에 저장된 상태를 다시 판단하는 것 자체가 틀린 일이다. */
final class TicketPersistenceMapper {

    private TicketPersistenceMapper() {
    }

    static Ticket toDomain(TicketJpaEntity entity) {
        return Ticket.rehydrate(entity.getId(), entity.getPrice(), entity.isReserved(),
                entity.isSuspended(), entity.getUserId());
    }

    static TicketJpaEntity toEntity(Ticket ticket) {
        return new TicketJpaEntity(ticket.getId(), ticket.getPrice(), ticket.isReserved(),
                ticket.isSuspended(), ticket.getUserId());
    }
}

package com.thinking.ticket.adapter.out.persistence;

import com.thinking.ticket.core.domain.User;

/* 회원은 조회만 하는 자리라 영속 모델 → 도메인 방향만 만든다.
 * 쓰지 않을 반대 방향까지 미리 만들면 아무도 검증하지 않는 코드가 남는다. */
final class UserPersistenceMapper {

    private UserPersistenceMapper() {
    }

    static User toDomain(UserJpaEntity entity) {
        return new User(entity.getId(), entity.getName());
    }
}

package com.thinking.ticket.adapter.out.persistence;

import com.thinking.ticket.core.domain.Ticket;
import com.thinking.ticket.core.domain.TicketAlreadyReservedException;
import com.thinking.ticket.core.port.out.TicketRepository;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

/* 아웃바운드 포트 TicketRepository를 JPA + MySQL로 구현한다.
 * 포트는 Core가 소유한 계약이고, 이 클래스는 그 계약을 특정 기술로 갚는 쪽이다.
 * 스프링 빈으로 등록해 두어야 조립 지점이 포트 자리에 꽂을 수 있다. */
@Repository
public class TicketPersistenceAdapter implements TicketRepository {

    private final TicketJpaRepository ticketJpaRepository;

    public TicketPersistenceAdapter(TicketJpaRepository ticketJpaRepository) {
        this.ticketJpaRepository = ticketJpaRepository;
    }

    @Override
    @Transactional(readOnly = true)
    public Ticket findById(long ticketId) {
        /* 없으면 null만 알린다 — '없음'을 예외로 번역하는 판단은 유스케이스의 몫이다. */
        return ticketJpaRepository.findById(ticketId)
                .map(TicketPersistenceMapper::toDomain)
                .orElse(null);
    }

    @Override
    @Transactional
    public void save(Ticket ticket) {
        if (!ticket.isReserved()) {
            /* 예약 이전 상태(등록·판매 중지 등)는 읽어온 행 전체를 그대로 기록한다. */
            ticketJpaRepository.save(TicketPersistenceMapper.toEntity(ticket));
            return;
        }

        /* 예약 확정만은 조건부 UPDATE로 넘긴다. 전체 저장으로 처리하면 동시에 들어온 두 예약 중
         * 나중 것이 앞선 예약을 덮어써 같은 티켓이 두 번 팔린다. */
        int updated = ticketJpaRepository.reserveIfNotReserved(ticket.getId(), ticket.getUserId());
        if (updated == 0) {
            /* 한 행도 못 바꿨다 = 그사이 다른 인스턴스가 먼저 예약을 확정했다.
             * 여기서 성공한 척하면 결제만 남고 예약은 남의 것이 된다. 도메인 예외로 올려 보낸다.
             * 프로토콜 응답으로의 번역은 인바운드 어댑터가 한다. */
            throw new TicketAlreadyReservedException();
        }
    }
}

package com.thinking.ticket.adapter.out.persistence;

import com.thinking.ticket.core.domain.User;
import com.thinking.ticket.core.port.out.UserRepository;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

/* 아웃바운드 포트 UserRepository의 JPA 구현. */
@Repository
public class UserPersistenceAdapter implements UserRepository {

    private final UserJpaRepository userJpaRepository;

    public UserPersistenceAdapter(UserJpaRepository userJpaRepository) {
        this.userJpaRepository = userJpaRepository;
    }

    @Override
    @Transactional(readOnly = true)
    public User findById(long userId) {
        /* 없음 판정은 유스케이스가 한다. */
        return userJpaRepository.findById(userId)
                .map(UserPersistenceMapper::toDomain)
                .orElse(null);
    }
}

package com.thinking.ticket.adapter.out.payment;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.thinking.ticket.core.port.out.ChargePort;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

/* 아웃바운드 포트 ChargePort를 외부 결제사 HTTP 호출로 구현한다.
 * Core는 결제사 SDK가 아니라 '청구'라는 역할에만 의존하므로, 결제사를 갈아끼워도
 * 바뀌는 것은 이 클래스뿐이다.
 *
 * 기반 URL은 pg.base-url에서 주입받는다. 기본값을 두지 않은 것은 의도적이다 —
 * 설정이 빠졌으면 엉뚱한 주소로 조용히 붙는 것보다 기동 시점에 실패하는 편이 낫다. */
@Component
public class PgChargeAdapter implements ChargePort {

    private final RestTemplate restTemplate;
    private final String baseUrl;

    public PgChargeAdapter(RestTemplateBuilder restTemplateBuilder, @Value("${pg.base-url}") String baseUrl) {
        this.restTemplate = restTemplateBuilder.build();
        this.baseUrl = baseUrl;
    }

    @Override
    public boolean charge(String paymentInfo, int amount) {
        try {
            ChargeResponse response = restTemplate.postForObject(
                    baseUrl + "/charge", new ChargeRequest(paymentInfo, amount), ChargeResponse.class);

            /* 승인 여부는 상태 코드가 아니라 본문이 정한다 — 거절도 200으로 온다.
             * 상태 코드로 판단하면 거절이 승인으로 뒤집혀 결제 없이 예약이 확정된다. */
            return response != null && response.approved();
        } catch (RestClientException e) {
            /* 통신이 실패했으면 승인받지 못한 것이다. 청구가 실제로 걸렸는지 알 수 없는 상태에서
             * 예약을 확정하는 쪽이 훨씬 비싼 오류다. */
            return false;
        }
    }

    /* 결제사 계약의 요청·응답 표현. 이 어댑터 밖으로 새어 나가면 안 되는 기술 세부라 중첩해 둔다. */
    record ChargeRequest(String paymentInfo, int amount) {
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    record ChargeResponse(boolean approved) {
    }
}
